using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace LightingBlocks.Editor {
public static class ForestRevisionBuilder {
const string Root="Assets/LightingBlocks/Art/SpectralForest",Art=Root+"/Twilight";
static T Load<T>(string path)where T:UnityEngine.Object=>AssetDatabase.LoadAssetAtPath<T>(path);
static Mesh Accent(string name,bool log){var root=new GameObject(name);var parts=new List<CombineInstance>();var colors=new List<Color>();
 for(int i=0;i<(log?4:3);i++){var p=GameObject.CreatePrimitive(log?PrimitiveType.Cylinder:PrimitiveType.Sphere);p.transform.SetParent(root.transform,false);p.transform.localPosition=log?new Vector3(i==0?0:.3f*(i-2),i==0?.18f:.28f,i==0?0:.32f*(i-2)):new Vector3((i-1)*.37f,.16f+i*.035f,(i%2)*.24f);p.transform.localRotation=log?Quaternion.Euler(i==0?0:35,0,90):Quaternion.Euler(0,i*47,17-i*13);p.transform.localScale=log?(i==0?new Vector3(.3f,1.25f,.3f):new Vector3(.12f,.45f,.12f)):new Vector3(.75f-i*.12f,.43f,.64f);var mesh=UnityEngine.Object.Instantiate(p.GetComponent<MeshFilter>().sharedMesh);var tint=log?new Color(.21f,.14f,.10f):new Color(.20f,.30f,.24f);mesh.colors=Enumerable.Repeat(tint,mesh.vertexCount).ToArray();parts.Add(new CombineInstance{mesh=mesh,transform=p.transform.localToWorldMatrix});}
 var result=new Mesh{name=name};result.CombineMeshes(parts.ToArray(),true,true);result.RecalculateBounds();string path=Art+"/Meshes/"+name+".asset";var old=Load<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(result,path);else {EditorUtility.CopySerialized(result,old);UnityEngine.Object.DestroyImmediate(result);result=old;}foreach(var part in parts)UnityEngine.Object.DestroyImmediate(part.mesh);UnityEngine.Object.DestroyImmediate(root);return result;}
public static void Apply(){
 if(EditorApplication.isPlaying)throw new Exception("Stop Play mode before applying the forest revision");EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");
 var game=UnityEngine.Object.FindAnyObjectByType<GameManager>();var forest=ForestWorld.For(game);var config=forest.configuration;
 if(config.worldRevision<1){config.islands[1].treeCount=config.islands[0].treeCount;config.islands[1].animalCount=config.islands[0].animalCount;config.islands[1].rabbitCount=config.islands[0].rabbitCount;config.islands[1].birdCount=config.islands[0].birdCount;config.islands[1].authoredWisdom.z=53.5f;config.islands[2].authoredWisdom.z+=Landscape.LegacyExpansion;game.exit.position+=Vector3.forward*Landscape.Expansion;
 // Relocate only authored third-island scenery, not the player's mutable save state.
 foreach(var t in game.blocksRoot.parent.GetComponentsInChildren<Transform>())if(t!=game.exit&&t.parent==game.blocksRoot.parent&&t!=game.blocksRoot&&t.name!="Spectral Forest"&&t.name!="Immersive Deeps"&&t.position.z>=48)t.position+=Vector3.forward*Landscape.Expansion;
 config.worldRevision=1;}
 config.coverMeshes=config.coverMeshes.Take(9).Concat(new[]{Accent("MossyRockCluster",false),Accent("FallenLog",true)}).ToArray();config.coverMaterials=config.coverMaterials.Take(9).Concat(new[]{config.coverMaterials[0],config.coverMaterials[0]}).ToArray();
 foreach(var name in new[]{"Rabbit","Bird"}){string path=Art+"/Models/"+name+".fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.animationCompression=ModelImporterAnimationCompression.Off;importer.motionNodeName=name+"Rig";var clips=importer.clipAnimations;foreach(var clip in clips){clip.keepOriginalOrientation=true;clip.keepOriginalPositionXZ=true;clip.keepOriginalPositionY=true;clip.lockRootHeightY=true;clip.loopPose=false;clip.loopTime=!clip.name.EndsWith("Takeoff")&&!clip.name.EndsWith("Landing");}importer.clipAnimations=clips;importer.SaveAndReimport();CreatureMotionRepair.Apply(name);var prefab=PrefabUtility.LoadPrefabContents(Art+"/Prefabs/"+name+".prefab");var animator=prefab.GetComponentInChildren<Animator>();animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.applyRootMotion=false;PrefabUtility.SaveAsPrefabAsset(prefab,Art+"/Prefabs/"+name+".prefab");PrefabUtility.UnloadPrefabContents(prefab);}
 TwilightBuilder.HabitatTexture(config);EditorUtility.SetDirty(config);AssetDatabase.SaveAssets();
 foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>()){int island=-1;bool floor=false;for(int i=0;i<3;i++){if(filter.name=="ShoreFloor"+i){island=i;floor=true;}if(filter.name=="ShoreCliff"+i)island=i;}if(island<0)continue;var mesh=floor?WorldDressing.FloorMesh(Landscape.Shores[island],island):WorldDressing.CliffMesh(Landscape.Shores[island],island);string path=Art+"/Meshes/Revision"+filter.name+".asset";var previous=Load<Mesh>(path);if(previous==null)AssetDatabase.CreateAsset(mesh,path);else{EditorUtility.CopySerialized(mesh,previous);UnityEngine.Object.DestroyImmediate(mesh);mesh=previous;}filter.sharedMesh=mesh;var collider=filter.GetComponent<MeshCollider>();if(collider!=null)collider.sharedMesh=mesh;}
 var bounds=WorldDressing.CourtBounds();game.cameraRig.bounds=new Vector2(bounds.max.x-2,bounds.max.z-2);game.cameraRig.minimumFocus=new Vector2(bounds.min.x+2,bounds.min.z+2);game.ApplyUpgrades();forest.Restore(forest.NewState(1907));forest.Build();EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveOpenScenes();AssetDatabase.SaveAssets();CreatureAudit.Run();File.WriteAllText("Library/ForestRevision.apply.txt","Applied animation import, equal-area island, speed and habitat revision. Areas="+Landscape.Area(Landscape.Shores[0])+", "+Landscape.Area(Landscape.Shores[1]));}
public static void Build(){TwilightBatch.Build();}
}}
